<template>
  <main class="public-views">
    <ViewComposer ref="viewComposer" />
    <header class="public-views-hero">
      <h1>See Henry through <span>your own lens</span></h1>
      <p class="public-views-dek">A <AiViewTerm class="view-term-definition" /> brings together material from across Henry&rsquo;s site around one perspective and links back to every original page it uses. It can begin with a question, a theme you want to understand, or an angle you want to follow. The <AiViewTerm plural /> visitors choose to share live here.</p>
      <div class="public-views-invitation">
        <div>
          <strong>Describe an angle that feels distinctly yours</strong>
          <p>Tell us what you want to understand about Henry. AI will connect the relevant pieces into a focused <AiViewTerm />.</p>
        </div>
        <button type="button" @click="createOwnView">
          <span class="public-views-invitation-button-copy">Compose a <AiViewTerm /></span>
          <ArrowUpRightIcon class="public-views-invitation-arrow" />
        </button>
      </div>
    </header>

    <section class="public-views-collection" aria-labelledby="public-views-collection-title">
      <div class="public-views-collection-heading">
        <div>
          <h2 id="public-views-collection-title">Shared <AiViewTerm plural /></h2>
          <p>See how other visitors have looked across Henry&rsquo;s work, experiences, and ideas.</p>
        </div>
      </div>
      <div class="timeline-tools public-views-tools">
        <label class="timeline-search public-views-search" aria-label="Search shared Views">
          <input v-model="query" class="timeline-search-input" type="search" autocomplete="off" spellcheck="false" placeholder="Search the collection" />
          <i class="fa fa-search timeline-search-icon" aria-hidden="true"></i>
        </label>
      </div>

      <div v-if="loading" class="public-views-status">Loading Shared <AiViewTerm plural />…</div>
      <div v-else-if="error" class="public-views-status">{{ error }}</div>
      <div v-else-if="searching" class="public-views-status">Looking through shared <AiViewTerm plural />…</div>
      <ol v-else-if="visibleViews.length" class="public-views-list">
        <li v-for="view in visibleViews" :key="view.id">
          <router-link :to="`/view/${view.id}`">
            <span class="public-view-question">&ldquo;{{ view.question }}&rdquo;</span>
            <strong>{{ view.title }}</strong>
            <span class="public-view-meta">{{ sourceLabel(view.source_count) }} · {{ dateLabel(view.created_at) }} <ArrowUpRightIcon /></span>
          </router-link>
        </li>
      </ol>
      <p v-else-if="query.trim()" class="public-views-status">No shared <AiViewTerm /> matches this search yet.</p>
      <p v-else class="public-views-status">No one has shared a <AiViewTerm /> yet.</p>
    </section>
  </main>
</template>

<script>
import { listPublicViews } from '../utils/viewShareSite';
import ViewComposer from './ViewComposer.vue';
import AiViewTerm from './ui/AiViewTerm.vue';

export default {
  name: 'PublicViewsPage',
  components: { AiViewTerm, ViewComposer },
  data() {
    return { views: [], searchResults: [], query: '', loading: true, searching: false, error: '' };
  },
  computed: {
    visibleViews() {
      const query = this.query.toLocaleLowerCase().trim();
      if (!query) return this.views.filter((view) => view.featured);
      return this.searchResults;
    },
  },
  watch: {
    query() {
      window.clearTimeout(this._searchTimer);
      const sequence = (this._searchSequence || 0) + 1;
      this._searchSequence = sequence;
      if (!this.query.trim()) {
        this.searchResults = [];
        this.searching = false;
        return;
      }
      this.searching = true;
      this._searchTimer = window.setTimeout(async () => {
        try {
          const data = await listPublicViews(this.query.trim());
          if (sequence === this._searchSequence) this.searchResults = data.views || [];
        } catch {
          if (sequence === this._searchSequence) {
            const query = this.query.toLocaleLowerCase().trim();
            this.searchResults = this.views.filter((view) => `${view.question} ${view.title}`.toLocaleLowerCase().includes(query));
          }
        } finally {
          if (sequence === this._searchSequence) this.searching = false;
        }
      }, 220);
    },
  },
  async mounted() {
    try {
      const data = await listPublicViews();
      this.views = data.views || [];
    } catch {
      this.error = 'Shared Views are temporarily unavailable.';
    } finally {
      this.loading = false;
    }
  },
  beforeUnmount() {
    window.clearTimeout(this._searchTimer);
  },
  methods: {
    sourceLabel(count) {
      return `${count} original ${count === 1 ? 'piece' : 'pieces'}`;
    },
    dateLabel(timestamp) {
      if (!timestamp) return 'Date unavailable';
      return new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
        .format(new Date(timestamp));
    },
    createOwnView() {
      this.$refs.viewComposer?.openComposer();
    },
  },
};
</script>

